import csv, json
from datetime import date

AUDIT_DATE = date(2026,3,31)

# Load accounts
accounts = {}
with open('/app/input/client_accounts.csv') as f:
    for r in csv.DictReader(f):
        accounts[r['account_id']] = r

# Load licences, build supersession map: for each licence id -> governing row
reg = {}
with open('/app/input/licensed_property_register.csv') as f:
    for r in csv.DictReader(f):
        reg[r['license_id']] = r

# Map every licence id to its governing (superseding) row id
def governing(lic_id):
    # find a row that supersedes lic_id (directly). Could be chains, but here single-level.
    for lid, row in reg.items():
        if row['supersedes'] == lic_id:
            return lid  # the successor; recurse in case of chains
    return lic_id

# Build full governing map handling chains
def governing_chain(lic_id):
    cur = lic_id
    while True:
        nxt = None
        for lid, row in reg.items():
            if row['supersedes'] == cur and lid != cur:
                nxt = lid
                break
        if nxt is None:
            return cur
        cur = nxt

gov_map = {lid: governing_chain(lid) for lid in reg}

def covers(lic_id_on_request, use_type, distribution):
    # Returns (covers_bool, governing_row)
    if lic_id_on_request == 'none' or lic_id_on_request == '' or lic_id_on_request is None:
        return (False, None)
    if lic_id_on_request not in reg:
        return (False, None)
    g_id = gov_map[lic_id_on_request]
    grow = reg[g_id]
    # 1. id appears in register (yes since lic_id in reg)
    # 2. license_type matches
    if grow['license_type'] != use_type:
        return (False, grow)
    # 3. covers_distribution
    cd = grow['covers_distribution']
    if cd != 'all' and distribution not in cd.split(';'):
        return (False, grow)
    # 4. valid_until
    vu = date.fromisoformat(grow['valid_until'])
    if vu < AUDIT_DATE:
        return (False, grow)
    return (True, grow)

def char_area_pct(req):
    if req['character_px_area'] in ('none','',None) or req['canvas_px_area'] in ('none','',None):
        return None
    return float(req['character_px_area'])/float(req['canvas_px_area'])*100.0

def to_bool(x):
    return str(x).strip().lower() == 'true'

def audit_request(req):
    findings = []
    dist = req['intended_distribution']
    # §3 character
    if req['character_property'] != 'none' and req['character_property'] != '' and req['character_property'] is not None:
        cleared = False
        # personal-use allowance
        if dist == 'personal_only':
            cleared = True
        # licence
        if not cleared:
            ok, grow = covers(req['character_license_id'], 'character', dist)
            if ok:
                # prominence cap
                cap = grow['max_character_area_pct']
                if cap == 'none' or cap == '' or cap is None:
                    cleared = True
                else:
                    capv = float(cap)
                    area = char_area_pct(req)
                    if area is not None and area <= capv + 1e-12:
                        cleared = True
                    # else breach
        if not cleared:
            findings.append('UNLICENSED_CHARACTER_USE')
    # §4 background
    bs = req['background_source']
    if bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    elif bs == 'third_party_licensed':
        ok, grow = covers(req['background_license_id'], 'background', dist)
        if not ok:
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    # customer_original -> never
    # §5 minor consent
    if to_bool(req['subject_is_minor']):
        ok = True
        if req['minor_consent_type'] == 'none' or req['minor_consent_type']=='':
            ok = False
        else:
            vu = date.fromisoformat(req['minor_consent_valid_until'])
            if vu < AUDIT_DATE:
                ok = False
            else:
                ct = req['minor_consent_type']
                if ct == 'basic':
                    if dist not in ('personal_only','client_internal'):
                        ok = False
                # publicity covers all
        if not ok:
            findings.append('MISSING_MINOR_CONSENT')
    # §6 commercial routing
    if dist in ('social_public','print_for_sale'):
        acc = accounts[req['account_id']]
        cleared6 = False
        if acc['agreement_status'] == 'active':
            mac = acc['master_agreement_covers']
            if mac != 'none' and dist in mac.split(';'):
                cleared6 = True
        if not cleared6:
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')
    # §7 alteration disclosure
    if req['alteration_level']=='substantive' and dist in ('social_public','print_for_sale'):
        if not to_bool(req['alteration_disclosure_on_file']):
            findings.append('ALTERATION_DISCLOSURE_MISSING')
    if not findings:
        return 'none'
    return '|'.join(findings)

# Load requests
rows = []
with open('/app/input/composite_request_log.csv') as f:
    for r in csv.DictReader(f):
        rows.append(r)

audited = [r for r in rows if r['intake_status'] != 'withdrawn']
withdrawn = [r for r in rows if r['intake_status'] == 'withdrawn']

results = {}
for r in audited:
    results[r['request_id']] = audit_request(r)

print("=== PER REQUEST ===")
order = ['UNLICENSED_CHARACTER_USE','THIRD_PARTY_BACKGROUND_UNLICENSED','MISSING_MINOR_CONSENT','COMMERCIAL_DISTRIBUTION_FLAG','ALTERATION_DISCLOSURE_MISSING']
for r in audited:
    rid = r['request_id']
    print(rid, r['account_id'], results[rid])

print("\nWithdrawn:", [r['request_id'] for r in withdrawn])
print("Audited count:", len(audited))

# Batch figures
request_count = len(audited)
flagged = [rid for rid,v in results.items() if v != 'none']
flagged_count = len(flagged)
compliant_count = request_count - flagged_count

def has_finding(rid, code):
    v = results[rid]
    if v=='none': return False
    return code in v.split('|')

character_count = sum(1 for rid in audited if has_finding(rid['request_id'],'UNLICENSED_CHARACTER_USE'))
background_count = sum(1 for rid in audited if has_finding(rid['request_id'],'THIRD_PARTY_BACKGROUND_UNLICENSED'))
consent_count = sum(1 for rid in audited if has_finding(rid['request_id'],'MISSING_MINOR_CONSENT'))
commercial_count = sum(1 for rid in audited if has_finding(rid['request_id'],'COMMERCIAL_DISTRIBUTION_FLAG'))
disclosure_count = sum(1 for rid in audited if has_finding(rid['request_id'],'ALTERATION_DISCLOSURE_MISSING'))
finding_total = sum(len(v.split('|')) if v!='none' else 0 for v in results.values())

# account rollup
acct_reqs = {}
for r in audited:
    acct_reqs.setdefault(r['account_id'], []).append(r['request_id'])

batch_share = flagged_count / request_count
print("\nBatch share:", batch_share)

escalated = []
acct_summary = {}
for aid in sorted(accounts):
    reqlist = acct_reqs.get(aid, [])
    rc = len(reqlist)
    fl = sum(1 for rid in reqlist if results[rid] != 'none')
    share = fl/rc if rc>0 else 0
    any3 = any(len(results[rid].split('|'))>=3 for rid in reqlist if results[rid]!='none')
    esc = share > batch_share or any3
    acct_summary[aid] = (accounts[aid]['account_type'], rc, fl, 'ESCALATION_REQUIRED' if esc else 'none')
    if esc: escalated.append(aid)
    print(aid, accounts[aid]['account_type'], rc, fl, 'ESCALATION_REQUIRED' if esc else 'none', 'share=%.4f'%share, 'any3=%s'%any3)

print("\n=== FIGURES ===")
print("request_count", request_count)
print("account_count", len(acct_reqs))
print("flagged_count", flagged_count)
print("compliant_count", compliant_count)
print("finding_total", finding_total)
print("character_count", character_count)
print("background_count", background_count)
print("consent_count", consent_count)
print("commercial_count", commercial_count)
print("disclosure_count", disclosure_count)
print("escalated_accounts", len(escalated))

# sanity
assert character_count+background_count+consent_count+commercial_count+disclosure_count == finding_total
assert sum(acct_summary[a][2] for a in acct_summary) == flagged_count
assert sum(acct_summary[a][1] for a in acct_summary) == request_count
print("\nALL SANITY CHECKS PASSED")
